/** True local SQL and relationships. Every project, set, cost, release and trial fixture rolls back. */
@EnabledIfEnvironmentVariable(named="PLM_COLLAB_TEST_DB_URL",matches="jdbc:postgresql://127\\.0\\.0\\.1:15432/plm_data_management\\?currentSchema=plm")
class PilotDeliveryLocalIntegrationTest {
    final ObjectMapper json=new ObjectMapper().findAndRegisterModules();JdbcTemplate jdbc;DataSourceTransactionManager tx;TransactionStatus scope;
    PilotAccessService access;PilotDeliveryQueue queue;PilotTrialService trials;DevelopmentFinanceService finance;CurrentUser admin;
    long platform,selected,otherColor,otherProject,item,otherItem,mold,process,bom,trial,attachment,baseInventory,baseSets;String tag;
    final byte[] original=new byte[]{0,1,2,(byte)255,0,0,37};
    @BeforeEach void begin() {
        var data=new DriverManagerDataSource(System.getenv("PLM_COLLAB_TEST_DB_URL"),"postgres",System.getenv("PLM_COLLAB_TEST_DB_PASSWORD"));jdbc=new JdbcTemplate(data);tx=new DataSourceTransactionManager(data);scope=tx.getTransaction(new DefaultTransactionDefinition());
        baseInventory=jdbc.queryForObject("select count(*) from plm_inventory",Long.class);baseSets=jdbc.queryForObject("select count(*) from plm_collaboration_mold_set",Long.class);tag="pilot-it-"+UUID.randomUUID().toString().replace("-","").substring(0,16);
        var user=jdbc.queryForList("select user_id,username,display_name from sys_user where deleted_flag=0 and status='active' and all_permissions=true order by user_id limit 1").get(0);admin=new CurrentUser(((Number)user.get("user_id")).longValue(),user.get("username").toString(),user.get("display_name").toString(),true);CurrentUserContext.set(admin);
        access=new PilotAccessService(jdbc,json);queue=new PilotDeliveryQueue(jdbc,json,new MockEnvironment(),access);trials=new PilotTrialService(jdbc,json,access,queue);finance=new DevelopmentFinanceService(jdbc,json,access,tx,mock(OperationLogService.class));
        platform=product(null,null);selected=product(platform,"Black");otherColor=product(platform,"Blue");otherProject=product(platform,"Other");
        item=archive("shared Apple");otherItem=archive("unselected Samsung");link(item,selected);link(item,otherColor);link(otherItem,otherProject);
        mold=jdbc.queryForObject("insert into plm_collaboration_mold_set(item_id,set_no,set_name,created_by,updated_by) values(?,1,?,?,?) returning mold_set_id",Long.class,item,tag,admin.username(),admin.username());
        for(String part:List.of("PC","TPU")){Long code=jdbc.queryForObject("insert into plm_product_mold_code(product_id,mold_code,mold_name) values(?,?,?) returning product_mold_code_id",Long.class,selected,tag+"-"+part,part);jdbc.update("insert into plm_collaboration_mold_part(mold_set_id,part_type,product_mold_code_id,original_mold_code) values(?,?,?,?)",mold,part,code,tag+"-"+part);}
        process=next("plm_process","process_id");jdbc.update("insert into plm_process(process_id,process_code,process_name,process_type,product_id,status,created_by,updated_by) values(?,?,?,'routing',?,'confirmed',?,?)",process,tag,tag,selected,admin.username(),admin.username());
        bom=next("plm_product_bom","product_bom_id");jdbc.update("insert into plm_product_bom(product_bom_id,product_id,bom_code,bom_type,version_no,bom_scope,status,currency_code,created_by,updated_by) values(?,?,?,'mbom','QA1','formal','released','CNY',?,?)",bom,selected,tag,admin.username(),admin.username());
        Long route=jdbc.queryForObject("insert into plm_product_bom_route(product_bom_id,product_id,process_id,route_code,route_name,shared_bom_group_code,route_variant_no) values(?,?,?,?,?,'QA','1') returning product_bom_route_id",Long.class,bom,selected,process,tag,tag);
        long material=next("plm_product_bom_item","product_bom_item_id");jdbc.update("insert into plm_product_bom_item(product_bom_item_id,product_bom_id,product_id,product_bom_route_id,line_no,item_code,item_name,quantity,uom_code,version_no,unit_cost_snapshot,currency_code,material_source,created_by,updated_by) values(?,?,?,?,1,'MANUAL-QA','manual material',2,'pcs','QA1',5,'CNY','manual',?,?)",material,bom,selected,route,admin.username(),admin.username());
        jdbc.update("insert into plm_product_bom_route_color(product_bom_id,product_bom_route_id,color_code,color_name) values(?,?,'QA','Black')",bom,route);
        trial=jdbc.queryForObject("insert into plm_pilot_trial(name,platform_ids,new_platform_id,project_ids,baseline,created_by,updated_by) values(?,?::jsonb,null,?::jsonb,'{}'::jsonb,?,?) returning trial_id",Long.class,tag,jsonText(List.of(platform)),jsonText(List.of(selected)),admin.userId(),admin.userId());
    }
    @AfterEach void rollback(){if(scope!=null&&!scope.isCompleted()){tx.rollback(scope);assertThat(jdbc.queryForObject("select count(*) from plm_product where product_id=?",Long.class,platform)).isZero();assertThat(jdbc.queryForObject("select count(*) from plm_inventory",Long.class)).isEqualTo(baseInventory);assertThat(jdbc.queryForObject("select count(*) from plm_collaboration_mold_set",Long.class)).isEqualTo(baseSets);}CurrentUserContext.clear();}
    long next(String table,String id){return jdbc.queryForObject("select coalesce(max("+id+"),0)+100000 from "+table,Long.class);}
    long product(Long parent,String color){long id=next("plm_product","product_id");jdbc.update("insert into plm_product(product_id,product_code,product_name,product_type,version_no,status,parent_product_id,model,color,created_by,updated_by) values(?,?,?,?,'QA1','released',?,?,?,?,?)",id,tag+"-"+id,tag+" "+Objects.toString(color,"Platform"),parent==null?"product_line":"model_variant",parent,parent==null?null:"Apple Integration",color,admin.username(),admin.username());return id;}
    long archive(String model){return jdbc.queryForObject("insert into plm_collaboration_item(product_line_id,style_name,compatible_models,created_by,updated_by) values(?,?,?,?,?) returning item_id",Long.class,platform,tag,model,admin.username(),admin.username());}
    void link(long itemId,long productId){jdbc.update("insert into plm_collaboration_item_project(item_id,project_id,linked_by) values(?,?,?)",itemId,productId,admin.username());}
    String jsonText(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException(e);}}
    ProductBom released(){var b=new ProductBom();b.setProductBomId(bom);b.setProductId(selected);b.setBomCode(tag);b.setVersionNo("QA1");b.setBomScope("formal");b.setBomType("mbom");b.setStatus("released");b.setCurrencyCode("CNY");return b;}
    Map<String,byte[]> entries(byte[] zip)throws Exception{Map<String,byte[]> data=new LinkedHashMap<>();try(var input=new ZipInputStream(new ByteArrayInputStream(zip),StandardCharsets.UTF_8)){java.util.zip.ZipEntry entry;while((entry=input.getNextEntry())!=null)data.put(entry.getName(),input.readAllBytes());}return data;}
    Set<Long> ids(JsonNode rows,String field){Set<Long> values=new LinkedHashSet<>();rows.forEach(row->values.add(row.path(field).asLong()));return values;}
    @Test void trueReleasedSnapshotAndOutboxRemainImmutableAndIdempotentWithNoExternalSend() {
        var releases=new BomReleaseDeliveryService(jdbc,json,queue,access);var b=released();releases.released(b);String snapshot=jdbc.queryForObject("select snapshot::text from plm_pilot_bom_release where bom_id=?",String.class,bom);releases.released(b);
        assertThat(jdbc.queryForObject("select count(*) from plm_pilot_bom_release where bom_id=?",Long.class,bom)).isEqualTo(1);assertThat(jdbc.queryForObject("select count(*) from plm_pilot_delivery_task where event_id=?",Long.class,"plm-bom:"+bom+":QA1")).isEqualTo(1);
        jdbc.update("update plm_product_bom_item set quantity=3 where product_bom_id=?",bom);assertThatThrownBy(()->releases.released(b)).hasMessageContaining("已固定");assertThat(jdbc.queryForObject("select snapshot::text from plm_pilot_bom_release where bom_id=?",String.class,bom)).isEqualTo(snapshot);assertThat(queue.enabled()).isFalse();
    }
    @Test void realSqlZipRespectsSelectedColorsBudgetScopesAndOriginalFinancialFacts()throws Exception {
        long sourceProcess=next("plm_process","process_id");jdbc.update("insert into plm_process(process_id,process_code,process_name,process_type,product_id,status,created_by,updated_by) values(?,?,?,'routing',?,'confirmed',?,?)",sourceProcess,tag+"-SOURCE",tag+" source",otherProject,admin.username(),admin.username());
        long sourceBom=next("plm_product_bom","product_bom_id");jdbc.update("insert into plm_product_bom(product_bom_id,product_id,bom_code,bom_type,version_no,bom_scope,status,currency_code,created_by,updated_by) values(?,?,?,'mbom','SOURCE','formal','released','CNY',?,?)",sourceBom,otherProject,tag+"-SOURCE",admin.username(),admin.username());
        long sourceRoute=jdbc.queryForObject("insert into plm_product_bom_route(product_bom_id,product_id,process_id,route_code,route_name,shared_bom_group_code,route_variant_no) values(?,?,?,?,?,'SOURCE','BASE') returning product_bom_route_id",Long.class,sourceBom,otherProject,sourceProcess,tag+"-SRC",tag+" source");
        long ownRoute=jdbc.queryForObject("select product_bom_route_id from plm_product_bom_route where product_bom_id=?",Long.class,bom);jdbc.update("update plm_product_bom set source_product_bom_id=?,source_product_id=? where product_bom_id=?",sourceBom,otherProject,bom);jdbc.update("update plm_product_bom_route set source_product_bom_route_id=? where product_bom_route_id=?",sourceRoute,ownRoute);
        long master=next("plm_process","process_id");jdbc.update("insert into plm_process(process_id,process_code,process_name,process_type,product_id,status,created_by,updated_by) values(?,?,?,'operation_master',NULL,'confirmed',?,?)",master,tag+"-MASTER","注塑母版",admin.username(),admin.username());long operation=next("plm_process","process_id");jdbc.update("insert into plm_process(process_id,process_code,process_name,process_type,product_id,parent_process_id,operation_master_process_id,sequence_no,status,created_by,updated_by) values(?,?,?,'operation',?,?,?,10,'confirmed',?,?)",operation,tag+"-OP","注塑工序",selected,process,master,admin.username(),admin.username());
        jdbc.update("insert into plm_process_production_operation_selection(product_id,product_bom_route_id,process_id,operation_process_id,route_version_no,selection_batch_no,confirmed_at,confirmed_by,created_by,updated_by) values(?,?,?,?,'QA1',?,now(),?,?,?)",selected,ownRoute,process,operation,tag,admin.username(),admin.username(),admin.username());
        long template=jdbc.queryForObject("select workflow_template_id from plm_workflow_template where flow_type='model_variant' and active_flag=1 order by workflow_template_id limit 1",Long.class);jdbc.update("update plm_product set workflow_template_id=?,current_step_no=1,timeline_last_operator_user_id=? where product_id=?",template,admin.userId(),selected);
        jdbc.update("insert into plm_operation_log(request_id,action,business_type,business_id,operator_user_id,operator_user_name,detail_json) values(?,'TIMELINE_CONFIRM','PRODUCT',?,?,?,'{\"nodeKey\":\"QA\",\"currentConfirmed\":true}')",tag,Long.toString(selected),admin.userId(),admin.username());
        long platformBudget=((Number)finance.createBudget(new CreateBudget("platform",tag,platform,null,null,null,"CNY"),null).get("budgetId")).longValue();long selectedBudget=((Number)finance.createBudget(new CreateBudget("mold",tag,platform,item,mold,platformBudget,"CNY"),null).get("budgetId")).longValue();long excludedBudget=((Number)finance.createBudget(new CreateBudget("mold",tag+" old",platform,otherItem,null,platformBudget,"CNY"),null).get("budgetId")).longValue();
        var imports=new DevelopmentFinanceImportService(finance,mock(DevelopmentErpReadClient.class));var preview=imports.previewErp(new ErpPreview(List.of(new ErpLine(tag,"actual","platform development","CNY",new BigDecimal("500"),"2026-10-12",null,1),new ErpLine(tag,"reversal","platform reversal","CNY",new BigDecimal("-100"),"2026-10-12",tag+"/actual",1))));imports.commitErp(new ErpCommit(preview.get("token").toString(),List.of(new ErpDecision(1,false,platform,null,null,platformBudget,"明确平台单据"),new ErpDecision(2,false,platform,null,null,platformBudget,"原单冲销"))),null);
        attachment=next("plm_attachment","attachment_id");String checksum=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(original));String key=tag+"/drawing.step";jdbc.update("insert into plm_attachment(attachment_id,owner_object_type,owner_object_id,file_category,file_name,original_file_name,storage_key,file_size,checksum,created_by,updated_by) values(?,'Product',?,'drawing','drawing.step','drawing.step',?,?,?,?,?)",attachment,selected,key,original.length,checksum,admin.username(),admin.username());
        long processAttachment=next("plm_attachment","attachment_id");jdbc.update("insert into plm_attachment(attachment_id,owner_object_type,owner_object_id,file_category,file_name,original_file_name,storage_key,file_size,created_by,updated_by) values(?,'Process',?,'drawing','private.step','private.step',?,0,?,?)",processAttachment,selected,tag+"/unselected-process.step",admin.username(),admin.username());
        long pdf=next("plm_attachment","attachment_id");String pdfKey=tag+"/drawing.pdf";jdbc.update("insert into plm_attachment(attachment_id,owner_object_type,owner_object_id,file_category,file_name,original_file_name,file_ext,storage_key,file_size,checksum,created_by,updated_by) values(?,'Product',?,'drawing','drawing.pdf','drawing.pdf','pdf',?,?,?,?,?)",pdf,selected,pdfKey,original.length,checksum,admin.username(),admin.username());
        long revision=next("plm_attachment","attachment_id");String revisionKey=tag+"/drawing-V2.step";jdbc.update("insert into plm_attachment(attachment_id,owner_object_type,owner_object_id,file_category,file_name,original_file_name,file_ext,storage_key,file_size,checksum,version_no,family_id,derived_pdf_attachment_id,released_at,released_by,released_by_user_id,created_by,updated_by) values(?,'Product',?,'drawing','drawing-V2.step','drawing-V2.step','step',?,?,?,'V2',?,?,now(),?,?,?,?)",revision,selected,revisionKey,original.length,checksum,attachment,pdf,admin.username(),admin.userId(),admin.username(),admin.username());
        var storage=mock(StorageClient.class);for(String fileKey:List.of(key,pdfKey,revisionKey)){when(storage.exists(fileKey)).thenReturn(true);when(storage.loadAsResource(fileKey)).thenReturn(new ByteArrayResource(original));}var exports=new PilotExportService(jdbc,json,trials,access,storage,mock(OperationLogService.class));var data=entries(exports.export(trial,null));
        assertThat(ids(json.readTree(data.get("data/products.json")),"product_id")).containsExactlyInAnyOrder(platform,selected);assertThat(ids(json.readTree(data.get("data/project_links.json")),"project_id")).containsExactly(selected).doesNotContain(otherColor,otherProject);assertThat(ids(json.readTree(data.get("data/collaboration_items.json")),"item_id")).containsExactly(item).doesNotContain(otherItem);assertThat(ids(json.readTree(data.get("data/budgets.json")),"budget_id")).containsExactlyInAnyOrder(platformBudget,selectedBudget).doesNotContain(excludedBudget);
        var expenses=json.readTree(data.get("data/expenses.json"));BigDecimal actual=BigDecimal.ZERO;for(var row:expenses){assertThat(row.path("source_system").asText()).isEqualTo("erp");actual=actual.add(row.path("erp_posted_amount").decimalValue());assertThat(row.path("approved_amount").isNull()).isTrue();}assertThat(actual).isEqualByComparingTo("400");
        assertThat(data.get("files/"+attachment+"/drawing.step")).isEqualTo(original);assertThat(ids(json.readTree(data.get("data/attachments.json")),"attachment_id")).containsExactlyInAnyOrder(attachment,pdf,revision).doesNotContain(processAttachment);assertThat(data).doesNotContainKey("files/"+processAttachment+"/private.step");assertThat(ids(json.readTree(data.get("data/referenced_processes.json")),"process_id")).contains(process,operation,master,sourceProcess);assertThat(ids(json.readTree(data.get("data/mold_parts.json")),"mold_set_id")).containsExactly(mold);
        assertThat(ids(json.readTree(data.get("data/referenced_boms.json")),"product_bom_id")).containsExactly(sourceBom);assertThat(ids(json.readTree(data.get("data/referenced_products.json")),"product_id")).contains(otherProject);assertThat(ids(json.readTree(data.get("data/products.json")),"product_id")).doesNotContain(otherProject,otherColor);assertThat(ids(json.readTree(data.get("data/production_operation_selection.json")),"operation_process_id")).containsExactly(operation);assertThat(ids(json.readTree(data.get("data/workflow_templates.json")),"workflow_template_id")).contains(template);assertThat(ids(json.readTree(data.get("data/workflow_history.json")),"operator_user_id")).contains(admin.userId());assertThat(ids(json.readTree(data.get("data/accounts.json")),"user_id")).contains(admin.userId());for(var account:json.readTree(data.get("data/accounts.json"))){assertThat(account.has("password_hash")).isFalse();assertThat(account.has("dingtalk_user_id")).isFalse();assertThat(account.has("phone")).isFalse();}
        assertThat(data.get("files/"+revision+"/drawing-V2.step")).isEqualTo(original);assertThat(data.get("files/"+pdf+"/drawing.pdf")).isEqualTo(original);
        var manifest=json.readTree(data.get("manifest.json"));for(var file:manifest.path("files")){byte[] bytes=data.get(file.path("path").asText());assertThat(HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes))).isEqualTo(file.path("sha256").asText());}assertThat(jdbc.queryForObject("select count(*) from plm_inventory",Long.class)).isEqualTo(baseInventory);
        jdbc.update("update plm_attachment set deleted_flag=1 where attachment_id=?",attachment);clearInvocations(storage);assertThatThrownBy(()->exports.export(trial,null)).hasMessageContaining("族根");verifyNoInteractions(storage);jdbc.update("update plm_attachment set deleted_flag=0 where attachment_id=?",attachment);
        long auditor=next("sys_user","user_id");String auditorName=tag+"-auditor";jdbc.update("insert into sys_user(user_id,user_code,user_name,login_name,username,display_name,department_name,password_hash,status,all_permissions,created_by,updated_by) values(?,?,?,?,?,?,'QA','unused-test-password','active',false,?,?)",auditor,auditorName,"回滚导出审计账号",auditorName,auditorName,"回滚导出审计账号",admin.username(),admin.username());jdbc.update("insert into plm_pilot_account(user_id,role_code,permissions,all_objects,created_by,updated_by) values(?,'finance','[\"finance:export\"]'::jsonb,false,?,?)",auditor,admin.username(),admin.username());for(long project:List.of(platform,selected))jdbc.update("insert into plm_pilot_scope(user_id,entity_type,entity_id) values(?,'product',?)",auditor,project);
        clearInvocations(storage);CurrentUserContext.set(new CurrentUser(auditor,tag+"-auditor","回滚导出审计账号",false));assertThatThrownBy(()->exports.export(trial,null)).hasMessageContaining("未授权");verifyNoInteractions(storage);CurrentUserContext.set(admin);
    }
}
